export function getFrequencyCatalogsSummary() {
  return Object.values(FREQUENCY_CATALOGS).map((cat) => ({
    key: cat.key,
    level: cat.level,
    title: cat.title,
    description: cat.description,
    totalWords: cat.words.length
  }));
}

export function generateDecksForProfile(db, profileId, presetKey, deckSize = 25) {
  const catalog = FREQUENCY_CATALOGS[presetKey];
  if (!catalog) {
    throw new Error(`Частотный каталог '${presetKey}' не найден.`);
  }

  const validDeckSize = Math.min(30, Math.max(10, Number(deckSize) || 25));
  const words = catalog.words;
  const totalDecks = Math.ceil(words.length / validDeckSize);

  const insertWordStmt = db.prepare(`
    INSERT INTO vocabulary (word, translation, example, level, profile_id, word_key, translation_key, next_review, review_count)
    VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, 0)
  `);

  const selectExistingWordStmt = db.prepare(`
    SELECT id FROM vocabulary WHERE profile_id = ? AND word_key = ?
  `);

  const insertGroupStmt = db.prepare(`
    INSERT OR IGNORE INTO vocabulary_groups (name, profile_id)
    VALUES (?, ?)
  `);

  const selectGroupStmt = db.prepare(`
    SELECT id FROM vocabulary_groups WHERE name = ? AND profile_id = ?
  `);

  const insertMemberStmt = db.prepare(`
    INSERT OR IGNORE INTO vocabulary_group_members (group_id, vocabulary_id)
    VALUES (?, ?)
  `);

  const createdGroups = [];
  let totalWordsAdded = 0;

  const transaction = db.transaction(() => {
    for (let deckIndex = 0; deckIndex < totalDecks; deckIndex++) {
      const startIdx = deckIndex * validDeckSize;
      const endIdx = Math.min(words.length, (deckIndex + 1) * validDeckSize);
      const deckWords = words.slice(startIdx, endIdx);

      const groupName = `${catalog.level}: Колода ${deckIndex + 1} (${startIdx + 1}–${endIdx})`;

      insertGroupStmt.run(groupName, profileId);
      const groupRow = selectGroupStmt.get(groupName, profileId);
      const groupId = groupRow ? groupRow.id : null;
      if (!groupId) continue;

      let groupWordsCount = 0;

      for (const w of deckWords) {
        const wordKey = String(w.word).trim().toLowerCase();
        const translationKey = String(w.translation).trim().toLowerCase();

        let wordRow = selectExistingWordStmt.get(profileId, wordKey);
        let wordId = wordRow ? wordRow.id : null;

        if (!wordId) {
          const insertRes = insertWordStmt.run(
            w.word,
            w.translation,
            w.example,
            w.level || catalog.level,
            profileId,
            wordKey,
            translationKey
          );
          wordId = insertRes.lastInsertRowid;
        }

        insertMemberStmt.run(groupId, wordId);
        groupWordsCount++;
        totalWordsAdded++;
      }

      createdGroups.push({
        groupId,
        name: groupName,
        wordCount: groupWordsCount
      });
    }
  });

  transaction();

  return {
    presetKey,
    level: catalog.level,
    totalGroupsCreated: createdGroups.length,
    totalWordsAdded,
    groups: createdGroups
  };
}

export const getFrequencyCatalogs = getFrequencyCatalogsSummary;
